 'use strict';
const mobileQuery=matchMedia('(pointer:coarse) and (max-width:1100px)');
function syncMobileMode(){document.documentElement.classList.toggle('mobile-play',mobileQuery.matches);keys={};touchPointers.clear();document.querySelectorAll('.touch-held').forEach(b=>b.classList.remove('touch-held'))}
mobileQuery.addEventListener('change',syncMobileMode);syncMobileMode();
function updateMobileHUD(){const switcher=document.querySelector('.touch-skill-page');if(switcher)switcher.hidden=player.classTier<4;const near=interactables.some(t=>Math.abs(player.x-t.x)<(t.radius||65)&&Math.abs(player.y-t.y)<48);const big=document.querySelector('.touch-jump');big.setAttribute('aria-label',near?'โต้ตอบ':'กระโดด');big.querySelector('span').innerHTML=near?'<svg viewBox="0 0 32 32" aria-hidden="true"><path d="M4 4h24v17H15l-8 7v-7H4Z" fill="none" stroke="currentColor" stroke-width="2"/><circle cx="10" cy="12" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="22" cy="12" r="2"/></svg>':'<svg viewBox="0 0 32 32" aria-hidden="true"><path d="m8 5 9 4-2 10 11 5v4H6v-8Z" fill="currentColor"/><path d="m21 3 4-2 3 5M23 2v12" fill="none" stroke="currentColor" stroke-width="2"/></svg>';for(const slot of ['q','w','e','r']){const mapped=slot==='e'?(window.mobileExtraSlot||'e'):slot;const source=$('hotbar'+mapped.toUpperCase()),target=$('touchSkill'+slot.toUpperCase());if(!source||!target)continue;target.dataset.key='Key'+mapped.toUpperCase();target.textContent=source.querySelector('span').textContent.replace(/^[QWER]\[/,'').replace(']','');target.disabled=source.disabled;target.hidden=false}}
window.addEventListener('blur',()=>{touchPointers.clear();document.querySelectorAll('.touch-held').forEach(b=>b.classList.remove('touch-held'))});

const joystick=$('touchJoystick');let joystickPointer=null;
function clearJoystick(){joystickPointer=null;for(const k of ['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'])keys[k]=false;joystick.querySelector('i').style.transform='translate(-50%,-50%)'}
function moveJoystick(e){if(e.pointerId!==joystickPointer)return;const r=joystick.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,len=Math.hypot(dx,dy),scale=Math.min(1,40/Math.max(1,len));keys.ArrowLeft=dx<-14;keys.ArrowRight=dx>14;keys.ArrowUp=dy<-18;keys.ArrowDown=dy>18;joystick.querySelector('i').style.transform='translate(calc(-50% + '+dx*scale+'px),calc(-50% + '+dy*scale+'px))'}
joystick.addEventListener('pointerdown',e=>{e.preventDefault();if(paused||screen!=='play'||joystickPointer!==null)return;joystickPointer=e.pointerId;joystick.setPointerCapture(e.pointerId);moveJoystick(e)});joystick.addEventListener('pointermove',moveJoystick);for(const type of ['pointerup','pointercancel','lostpointercapture'])joystick.addEventListener(type,e=>{if(e.pointerId===joystickPointer)clearJoystick()});window.addEventListener('blur',clearJoystick);

const switchSkills=document.createElement("button");switchSkills.textContent="E ⇄ R";switchSkills.className="touch-skill-page";switchSkills.setAttribute("aria-label","สลับช่องสกิลขั้น 3 และ 4");switchSkills.onclick=()=>{window.mobileExtraSlot=window.mobileExtraSlot==="r"?"e":"r";updateMobileHUD()};switchSkills.hidden=true;$("touchControls").append(switchSkills);

